import functools
import inspect
import itertools
import logging
import sys
import typing

from jsilib._compat import asyncio

logger = logging.getLogger('jsilib.utils')

_unique_id_generators = {}


def python_version_gt(*other) -> bool:
    """Return True if current Python version is greater than ``other``."""
    return sys.version_info[:len(other)] > other


def next_unique_id(origin: typing.Hashable = None, start: int=0, step: int=1) -> int:
    """Generate next integer number in the sequence (starting from 1), for
    given *origin*.

    :param origin:
        Counter origin.

        For different values of this parameter, different unique ID generators
        will be used. For example, this can be used to count instances of a
        particular class if class object is used as *origin*.

        If omitted, then a common global counter will be used.
    """
    return next(_unique_id_generators.setdefault(origin, itertools.count(start=start, step=step)))


def bytes_to_hex_string(data: bytes) -> str:
    """Convert bytes into hexadecimal string."""
    return ' '.join(f'{x:0{2}x}' for x in data)


def format_binary_payload(data: bytes, prefix_length: int=16, postfix_length: int=8) -> str:
    """Shrink large binary payload into shorter hexadecimal string that can be
    used for debugging purposes.

    :param data:
        Binary data to be processed

    :param prefix_length:
        Number of starting bytes to always include in the output.

    :param postfix_length:
        Number of ending bytes to always include in the output.
    """
    data_len = len(data)
    if data_len == 0 or (prefix_length == 0 and postfix_length == 0):
        return f'[{data_len} bytes]'
    if data_len <= prefix_length + postfix_length:
        return f"{bytes_to_hex_string(data)} [{data_len} bytes]"
    if prefix_length == 0:
        return f"... {bytes_to_hex_string(data[-postfix_length:])} [{data_len} bytes]"
    if postfix_length == 0:
        return f"{bytes_to_hex_string(data[:prefix_length])} ... [{data_len} bytes]"
    return f"{bytes_to_hex_string(data[:prefix_length])} ..."\
        f" {bytes_to_hex_string(data[-postfix_length:])} "\
        f"[{data_len} bytes]"


@functools.lru_cache(maxsize=1024)
def get_obj_addr(obj: typing.Any) -> str:
    """Get address of given *obj* and return as a hexadecimal string."""
    return f'0x{id(obj):x}'


def unpack_dict(d: dict, *keys: str):
    """A generator yielding values of *d* dictionary for given *keys* in order
    specified by *keys*.

    Can be used for a one-line unpacking of several dict values:

    .. doctest::

        >>> d = {'a': 1, 'b': 2, 'c': 3}
        >>> a, c = unpack_dict(d, 'a', 'c')
        >>> (a, c)
        (1, 3)
    """
    for k in keys:
        yield d[k]


def log_exceptions(logger: logging.Logger, logger_method_to_use: str = 'warning'):
    """Decorate function or method to log exceptions it throws using provided
    *logger*.

    Once exception is logger, it is re-raised. This is handy helper to be used
    with async task functions that does not print errors out-of-the-box.

    :param logger:
        Logger to log exceptions to

    :param logger_method_to_use:
        Name of logger method to use for logging exceptions.
    """
    logger_method = getattr(logger, logger_method_to_use)

    def decorator(func):
        message = f'An exception was raised by {func!r}:'
        if inspect.iscoroutinefunction(func):

            @functools.wraps(func)
            async def proxy(*args, **kwargs):
                try:
                    return await func(*args, **kwargs)
                except asyncio.CancelledError:
                    raise
                except Exception:
                    logger_method(message, exc_info=True)
                    raise
        else:

            @functools.wraps(func)
            def proxy(*args, **kwargs):
                try:
                    return func(*args, **kwargs)
                except asyncio.CancelledError:
                    raise
                except Exception:
                    logger_method(message, exc_info=True)
                    raise

        return proxy

    return decorator


class ExportList(list):
    """A helper for making ``__all__`` members in modules.

    Can be used as a decorator to automatically populate ``__all__`` list with
    exported objects.
    """
    T = typing.TypeVar('T')

    def __call__(self, cls_or_func: T):
        self.append(cls_or_func.__name__)
        return cls_or_func
